function db(): PDO { static $pdo; global $config; if (!$pdo) $pdo = new PDO('mysql:host='.$config['db_host'].';dbname='.$config['db_name'].';charset=utf8mb4', $config['db_user'], $config['db_pass'], [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); return $pdo; }
function e($s): string { return htmlspecialchars((string)$s, ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function keyBytes(): string { global $config; $key=base64_decode($config['encryption_key'] ?? '', true); if ($key===false || strlen($key)!==32) throw new RuntimeException('Encryption key config salah: harus base64 dari 32 byte acak.'); return $key; }
function encryptPassword(string $plain): array { $nonce=random_bytes(12); $tag=''; $cipher=openssl_encrypt($plain,'aes-256-gcm',keyBytes(),OPENSSL_RAW_DATA,$nonce,$tag); if ($cipher===false) throw new RuntimeException('Enkripsi password gagal.'); return [base64_encode($cipher),bin2hex($nonce),bin2hex($tag)]; }
function decryptPassword(array $u): string { $p=openssl_decrypt(base64_decode($u['password_ciphertext']), 'aes-256-gcm', keyBytes(), OPENSSL_RAW_DATA, hex2bin($u['password_nonce']), hex2bin($u['password_tag'])); return $p===false?'(gagal didekripsi)':$p; }
function me(): ?array { return $_SESSION['user'] ?? null; }
function requireLogin(): array { if (!me()) { header('Location: index.php'); exit; } return me(); }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function checkCsrf(): void { if(!hash_equals(csrf(),$_POST['csrf']??'')){http_response_code(419);exit('Sesi formulir kedaluwarsa. Muat ulang halaman.');} }
function notifyUser(int $uid, ?int $rid, string $text): void { $s=db()->prepare('INSERT INTO notifications(user_id,request_id,body) VALUES(?,?,?)');$s->execute([$uid,$rid,$text]); }
function requestRow(int $id): array { $s=db()->prepare('SELECT r.*,u.name requester,e.name editor FROM requests r JOIN users u ON u.id=r.requester_id JOIN users e ON e.id=r.editor_id WHERE r.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Konten tidak ditemukan');}return $r; }
function canView(array $r,array $u): bool { return $u['role']==='superadmin'||$u['role']==='admin'||($u['role']==='editor'&&(int)$r['editor_id']===(int)$u['id']); }
