n: index.php?request='.$rid);exit; }
 if($action==='add_option'||$action==='delete_option'||$action==='user_access'||$action==='change_password'){if($action==='change_password'){ $q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([$u['id']]);$meRow=$q->fetch();if(!hash_equals(decryptPassword($meRow),$_POST['current_password']??''))throw new RuntimeException('Password saat ini tidak sesuai.');$new=$_POST['new_password']??'';if(strlen($new)<10)throw new RuntimeException('Password baru minimal 10 karakter.');[$c,$n,$t]=encryptPassword($new);db()->prepare('UPDATE users SET password_ciphertext=?,password_nonce=?,password_tag=? WHERE id=?')->execute([$c,$n,$t,$u['id']]);$_SESSION['flash']='Password berhasil diganti.';header('Location: index.php?settings=1');exit;}if($u['role']!=='superadmin')throw new RuntimeException('Hanya Super Admin yang dapat mengubah pengaturan.');if($action==='add_option'){if(!in_array($_POST['group'],['content_type','ratio','platform'],true))throw new RuntimeException('Kategori tidak valid.');db()->prepare('INSERT IGNORE INTO options(option_group,label) VALUES(?,?)')->execute([$_POST['group'],trim($_POST['label'])]);}elseif($action==='delete_option'){db()->prepare('UPDATE options SET active=0 WHERE id=?')->execute([(int)$_POST['option_id']]);}else{db()->prepare('UPDATE users SET caption_access=?,allow_multiple_types=?,allow_multiple_ratios=? WHERE id=?')->execute([isset($_POST['caption_access'])?1:0,isset($_POST['multi_types'])?1:0,isset($_POST['multi_ratios'])?1:0,(int)$_POST['user_id']]);}$_SESSION['flash']='Pengaturan berhasil disimpan.';header('Location: index.php?settings=1');exit; }
