']==='superadmin'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="reopen"><input type="hidden" name="request_id" value="<?=$detail['id']?>"><button class="secondary w-full">Buka kembali diskusi</button></form><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="set_status"><input type="hidden" name="request_id" value="<?=$detail['id']?>"><select name="status"><option value="scheduled">Terjadwal</option><option value="in_progress">Dikerjakan</option><option value="revision">Revisi</option><option value="approved">Approved</option><option value="published">Publish</option></select><button class="secondary">Ubah status</button></form><?php endif?><h3>Semua file</h3><?php foreach($files as $f):?><a class="file-link" href="index.php?download=<?=$f['id']?>">⬇ <?=e($f['original_name'])?><small><?=e($f['file_kind'])?> · oleh <?=e($f['uploader'])?></small></a><?php endforeach?></aside></div>
<?php else:?><div class="page-head"><div><p class="eyebrow">RUANG KERJA DIGITAL</p><h1>Halo, <?=e($u['name'])?> <span class="wave">✦</span></h1><p class="muted">Pantau jobdesk dan kolaborasi konten di satu tempat.</p></div><?php if(in_array($u['role'],['admin','superadmin'],true)):?><a href="#new-request" class="primary">＋ Ajukan konten</a><?php endif?></div><div class="stat-row"><div class="stat"><small>Total jobdesk</small><b><?=count($requests)?></b></div><div class="stat"><small>Dalam pengerjaan</small><b><?=count(array_filter($requests,fn($r)=>in_array($r['status'],['scheduled','in_progress','revision'])))?></b></div><div class="stat"><small>Menunggu publish</small><b><?=count(array_filter($requests,fn($r)=>$r['status']==='approved'))?></b></div></div><section class="panel"><div class="section-title"><h2>Daftar konten</h2><span class="muted">Pengingat deadline otomatis H-3</span></div><?php if(!$requests):?><div class="empty">Belum ada jobdesk. Konten yang baru dibuat akan muncul di sini.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Konten</th><th>Pengaju / Editor</th><th>Deadline</th><th>Status</th></tr></thead><tbody><?php foreach($requests as $r):$days=(int)floor((strtotime($r['deadline'])-time())/86400);?><tr><td><a class="content-title" href="index.php?request=<?=$r['id']?>"><?=e($r['title'])?></a><small>#<?=$r['id']?></small></td><td><?=e($r['requester'])?><small>Editor: <?=e($r['editor'])?></small></td><td><?=e(date('d M Y H:i',strtotime($r['deadline'])))?><?php if($days>=0&&$days<=3&&$r['status']!=='published'):?><small class="deadline-alert">⚠ Deadline kurang dari 3 hari</small><?php endif?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
<?php if(in_array($u['role'],['admin','superadmin'],true)):?><section class="panel" id="new-request"><h2>Ajukan jobdesk konten</h2><form method="post" enctype="multipart/form-data" class="request-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create_request"><label>Nama / judul konten<input name="title" required maxlength="200" placeholder="Contoh: Kampanye layanan publik"></label><label>Brief design<textarea name="brief" required placeholder="Jelaskan konsep, pesan, referensi visual..."></textarea></label><div class="form-grid"><label>Editor yang mengerjakan<select name="editor_id" required><option value="">Pilih editor</option><?php foreach(db()->query("SELECT id,name FROM users WHERE role='editor' AND active=1 ORDER BY name") as $ed):?><option value="<?=$ed['id']?>"><?=e($ed['name'])?></option><?php endforeach?></select></label><label>Deadline<input type="datetime-local" name="deadline" required></label><label>Jadwal publish (opsional)<input type="datetime-local" name="publish_at"></label></div><div class="choice-group"><b>Platform</b><div class="choices"><?php optSelect('platform',$activeOptions)?></div></div><div class="choice-group"><b>Jenis konten</b><div class="choices"><?php optSelect('content_type',$activeOptions)?></div></div><div class="choice-group"><b>Rasio</b><div class="choices"><?php optSelect('ratio',$activeOptions)?></div></div><label>Bahan / referensi untuk editor<input type="file" name="attachment" accept="image/*,video/*,.pdf,.zip"></label><button class="primary">Buat jobdesk</button></form></section><?php endif?>
<?php endif?><?php endif?></main><?php if($u):?><div id="notification" class="notification" aria-live="polite"></div><script>let seen=new Set();async function poll(){try{const r=await fetch('index.php?api=notifications',{cache:'no-store'});if(!r.ok)return;for(const n of await r.json()){if(seen.has(n.id))continue;seen.add(n.id);const box=document.getElementById('notification');box.innerHTML='<b>🔔 Notifikasi baru</b><p>'+escapeHtml(n.body)+'</p>'+(n.request_id?'<a href="index.php?request='+n.request_id+'">Buka jobdesk →</a>':'');box.classList.add('show');setTimeout(()=>box.classList.remove('show'),7000)}}catch(e){}}function escapeHtml(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}poll();setInterval(poll,5000);</script><?php endif?></body></html>
